test('vatSummary groups by VAT rate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'BOOK', qty: 5 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  const rates = result.map((item) => item.rate).sort((a, b) => b - a);
  assert.deepEqual(rates, [21, 9, 0]);
});

test('vatSummary sorts by rate descending', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'STICKER', qty: 100, discountPercent: 0 },
      { sku: 'BOOK', qty: 5, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  assert.ok(result[0].rate > result[1].rate);
  assert.ok(result[1].rate > result[2].rate);
});

test('vatSummary calculates base correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  const item = result[0];
  const lineTotal = 100 * 150;
  assert.equal(item.base, lineTotal);
});

test('vatSummary calculates base with discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  const item = result[0];
  const lineTotal = 100 * 150;
  const lineDiscount = Math.round(lineTotal * 10 / 100);
  const expectedBase = lineTotal - lineDiscount;
  assert.equal(item.base, expectedBase);
});

test('vatSummary calculates VAT correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  const item = result.find((r) => r.rate === 21);
  const lineTotal = 100 * 150;
  const expectedVat = Math.round(lineTotal * 21 / 100);
  assert.equal(item.vat, expectedVat);
